def bio_spans(tags):
    spans, start, kind = set(), None, None
    for i, tag in enumerate([*tags, "O"]):
        if not (tag.startswith("I-") and tag[2:] == kind):
            if start is not None:
                spans.add((kind, start, i))
            start, kind = (i, tag[2:]) if tag != "O" else (None, None)
    return spans

